 document.addEventListener('aiw:sdd-edit',e=>{const t=e.detail;if(t?.chapter!==5||bridge?.state.chapter!==5||bridge.state.tab!=='work')return;const c=records().find(x=>x.ref===t.ref);if(!c)return;bridge.state.selected=c.id;editComponent(c.id,['architecturalSolution','rationale','source','prop-statement'].includes(t.field)?2:['logicalIds','dataIds'].includes(t.field)?1:0);document.querySelector('.a-dialog [name="'+t.field+'"]')?.focus({preventScroll:true});},{signal});
