 function solutionFields(c){const p=project(),rows=[...(c.properties||[]),{}].slice(0,PROPERTY_LIMIT),concerns=[['','Choose a quality concern or a driver'],...QUALITY_TYPES.map(t=>[t.id,t.name]),...(p.quality?.drivers||[]).map(d=>[d.id,driverCode(p,d)+' · '+d.title])],box=c.id?componentContainer(p,c):null;
  return '<fieldset class="a-properties"><legend>Quality properties</legend>'+rows.map((x,i)=>'<div class="l-form-grid">'+fComponent('prop-concern',x.concern||'',{item:i,label:'Quality concern '+(i+1),options:concerns})+fComponent('prop-statement',x.statement||'',{item:i,label:'Property '+(i+1)})+fComponent('prop-mechanism',x.mechanism||'',{item:i,label:'Mechanism '+(i+1)})+fComponent('prop-source',x.source||'',{item:i,label:'Source '+(i+1)})+'</div>').join('')+'</fieldset>'
   +fComponent('architecturalSolution',c.architecturalSolution||'')+fComponent('patternIds',c.patternIds||[],{options:[...STYLES,...PATTERNS].map(x=>({id:x.id,title:x.name}))})
   +fComponent('containerId',c.containerId||'',{options:[['',box?.derived?'Derived: '+box.ref+' · '+box.title:'Derived from its compute need'],...(p.technologyRealisation?.records||[]).map(r=>[r.id,(r.ref||r.id)+' · '+r.title])]});}
 function componentForm(c,ghost=false){
  const g=logicalGraph(project());
  return '<form id="a-component-form">'+(ghost?'<div class="l-before-after"><div><small>Current model</small><p>'+esc(c.rationale)+'</p></div><div><small>Reviewable proposal</small><p>'+esc(c.effect)+'</p>'+(c.newData?'<p>Also adds the owned data record <b>'+esc(c.newData.title)+'</b>.</p>':'')+(c.library?'<p>From '+esc(originText(c))+'.</p>':'')+'</div></div>'+proposedHTML(c):'')+steps()+
   '<section data-a-panel="0">'+fComponent('title',c.title)+'<div class="l-form-grid"><label class="l-field"><span>Component kind</span><select name="kind">'+COMPONENT_KINDS.map(k=>'<option value="'+k+'"'+(c.kind===k?' selected':'')+'>'+esc(componentKindName(k))+'</option>').join('')+'</select></label>'+fComponent('owner',c.owner)+'</div>'+fComponent('purpose',c.purpose)+fComponent('boundary',c.boundary)+'<div class="l-form-grid">'+fComponent('inputs',c.inputs)+fComponent('outputs',c.outputs)+'</div>'+B('step','Next: traceability','',{'data-a-step':1})+'</section>'+
   '<section data-a-panel="1" hidden>'+allocationFields(c)+fComponent('requirementGroupIds',c.requirementGroupIds||[],{options:requirementGroups(project()).map(x=>({id:x.id,strong:x.id,title:x.title})),empty:'No requirement group yet.'})+fComponent('dataIds',c.dataIds||[],{options:g.nodes.filter(n=>n.layer==='data').map(n=>({id:n.id,title:n.title})),help:'Select the authoritative records it owns. Consuming a record does not make this component its owner.'})+dataPick('consumesDataIds','Data definitions it reads or receives. Its prose inputs stay as description.',c.consumesDataIds)+dataPick('producesDataIds','Data definitions it writes or emits. Its prose outputs stay as description.',c.producesDataIds)+fComponent('decisionIds',c.decisionIds||[],{options:project().decisions.records.map(d=>({id:d.id,strong:d.id,title:d.question,note:(decisionCurrent(project(),d)?'Architect accepted':'Draft or requires review')+' · '+governanceLabel(d,project())})),help:'Requirements, drivers, and decisions already linked to the logical responsibilities are inherited automatically.'})+B('step','Next: review','',{'data-a-step':2})+'</section>'+
   '<section data-a-panel="2" hidden>'+fComponent('rationale',c.rationale)+fComponent('source',c.source)+fComponent('technologyNeeds',c.technologyNeeds)+fComponent('assumptions',c.assumptions)+solutionFields(c)+'<label class="l-checkbox"><input type="checkbox" name="assumptionsResolved"'+(c.assumptionsResolved?' checked':'')+'>I have reviewed and resolved these assumptions.</label>'+
   (ghost?(c.library?'':fComponent('relationship',c.relationship)+fComponent('condition',c.condition)+fComponent('failure',c.failure))+'<label class="l-checkbox"><input type="checkbox" name="reviewed" required>I have reviewed the proposed component, allocations, and '+(c.library?'what is proposed with it.':'interactions.')+'</label>':'<label class="l-field"><span>Component design state</span><select name="status">'+[['draft','Working draft'],['candidate','Candidate design'],['reviewed','Design reviewed']].map(([id,t])=>'<option value="'+esc(id)+'"'+(c.status===id?' selected':'')+'>'+t+'</option>').join('')+'</select></label>')+
   '<p class="l-note">'+(c.ref?c.ref+' stays stable through revisions. ':'')+'Design review does not grant governance approval or prove runtime behaviour.</p>'+(c.history?.length?'<details><summary>Recent revisions</summary>'+c.history.slice(-5).reverse().map(h=>'<p>r'+h.revision+' · '+esc(h.title)+'<br>'+esc(h.boundary)+'</p>').join('')+'</details>':'')+'</section>'+
   (ghost?B('preview-edits','Preview these edits on the model','gold'):'')+actions(ghost?'Accept reviewed proposal':c.id?'Preview impact':'Save component')+'</form>';
 }
 const blankComponent=logicalId=>({title:'',kind:'service',purpose:'',boundary:'',owner:'',inputs:'',outputs:'',rationale:'',source:'',technologyNeeds:'',assumptions:'',status:'draft',dataIds:[],consumesDataIds:[],producesDataIds:[],decisionIds:[],allocations:logicalId?[{logicalId,scope:responsibility(project())(logicalId)?.boundary||''}]:[]});
 function editComponent(id,initial=0,logicalId,draft){
  const pending=window.aiwInterfaceImpact?.commandFor('realisation.component',id);const c=draft||(pending?{...record(id),...pending.payload}:null)||record(id)||blankComponent(logicalId);
  dialog(c.id?'Edit '+c.ref+' · '+c.title:'Create an application component',componentForm(c),'component',{id:c.id});step(initial);
 }
 function readComponentForm(form){const fd=new FormData(form),raw=Object.fromEntries(fd);raw.dataIds=fd.getAll('dataIds');raw.consumesDataIds=fd.getAll('consumesDataIds');raw.producesDataIds=fd.getAll('producesDataIds');raw.decisionIds=fd.getAll('decisionIds');raw.requirementGroupIds=fd.getAll('requirementGroupIds');raw.patternIds=fd.getAll('patternIds');raw.allocations=fd.getAll('logicalIds').map(id=>({logicalId:id,scope:String(fd.get('scope:'+id)||''),role:String(fd.get('role:'+id)||'')}));raw.properties=[];for(let i=0;fd.has('prop-statement-'+i);i++){const x={concern:String(fd.get('prop-concern-'+i)||''),statement:String(fd.get('prop-statement-'+i)||'').trim(),mechanism:String(fd.get('prop-mechanism-'+i)||''),source:String(fd.get('prop-source-'+i)||'')};if(x.statement||x.concern)raw.properties.push(x);}for(const k of Object.keys(raw))if(k.startsWith('prop-'))delete raw[k];raw.assumptionsResolved=fd.has('assumptionsResolved');raw.reviewed=fd.has('reviewed');return raw}
 function interactionOptions(value){return logicalGraph(project()).nodes.filter(n=>n.layer!=='logical').map(n=>'<option value="'+esc(n.id)+'"'+(n.id===value?' selected':'')+'>'+esc((n.ref?n.ref+' · ':'')+n.title)+' · '+esc(n.layer)+'</option>').join('')}
